      "old": "def load_api_key(cfg: Dict[str, Any], forbidden_roots: List[Path]) -> Tuple[str, str]:\n    env_name = cfg.get('api_key_env') or DEFAULT_API_KEY_ENV\n    env_value = os.environ.get(env_name)\n    if env_value and env_value.strip():\n        return env_value.strip(), 'env'\n    raw_file = cfg.get('api_key_file')\n    if raw_file:\n        return read_api_key_file(raw_file, forbidden_roots), 'file'\n    raise BridgeError(\n        'missing_api_key',\n        'no API key available: set the configured environment variable or api_key_file',\n    )",
      "new": "def validate_api_key_header_value(key: str) -> None:\n    '''Reject key material that cannot safely be placed in an HTTP header.'''\n    for char in key:\n        code = ord(char)\n        if code < 0x21 or code > 0x7e:\n            raise BridgeError(\n                'bad_api_key',\n                'API key contains characters that cannot be sent in an HTTP header',\n            )\n\n\ndef load_api_key(cfg: Dict[str, Any], forbidden_roots: List[Path]) -> Tuple[str, str]:\n    env_name = cfg.get('api_key_env') or DEFAULT_API_KEY_ENV\n    if not isinstance(env_name, str) or not env_name.strip():\n        env_name = DEFAULT_API_KEY_ENV\n    env_value = os.environ.get(env_name)\n    if env_value and env_value.strip():\n        key = env_value.strip()\n        validate_api_key_header_value(key)\n        return key, 'env'\n    raw_file = cfg.get('api_key_file')\n    if raw_file:\n        key = read_api_key_file(raw_file, forbidden_roots)\n        validate_api_key_header_value(key)\n        return key, 'file'\n    raise BridgeError(\n        'missing_api_key',\n        'no API key available: set the configured environment variable or api_key_file',\n    )"
