      "file": "tools/claude-advisor/preparation/draft/bridge.py",
      "old": "def run_consult(\n    config_path: Path,\n    task: Any,\n    role: Any,\n    context: Any = None,\n    root: Any = None,\n    files: Any = None,\n    opener: Any = None,\n) -> Dict[str, Any]:\n    if not isinstance(role, str) or role not in ROLE_PROMPTS:\n        raise BridgeError(\n            'invalid_arguments',\n            'role must be one of: ' + ', '.join(ROLE_PROMPTS),\n        )\n    task_text = validate_text('task', task, MAX_TASK_CHARS, required=True)\n    context_text = validate_text('context', context, MAX_CONTEXT_CHARS, required=False)\n\n    info = load_config(config_path)\n    if info['errors']:\n        raise BridgeError('config_error', '; '.join(info['errors']))\n    cfg = info['values']\n    validate_call_config(cfg)\n\n    rel_files = list(files) if isinstance(files, (list, tuple)) else []\n    if rel_files and not root:\n        raise BridgeError('bad_root', '--root is required when --files is used')\n\n    forbidden_roots = default_workspace_roots()\n    if root:\n        try:\n            forbidden_roots.append(Path(root).resolve())\n        except OSError:\n            pass\n\n    api_key, key_source = load_api_key(cfg, forbidden_roots)\n    entries = collect_files(root, rel_files) if rel_files else []\n    files_block = render_files(entries) if entries else ''\n    payload = build_payload(cfg, role, task_text, context_text, files_block)\n    raw = call_anthropic(cfg, payload, api_key, opener=opener)\n\n    result = build_result(cfg, role, raw)\n    result['key_source'] = key_source\n    result['files_used'] = [entry['path'] for entry in entries]\n    return result",
      "new": "def run_consult(\n    config_path: Path,\n    task: Any,\n    role: Any,\n    context: Any = None,\n    root: Any = None,\n    files: Any = None,\n    opener: Any = None,\n    user_request: Any = None,\n) -> Dict[str, Any]:\n    if user_request is None or not isinstance(user_request, str) or not user_request.strip():\n        raise BridgeError(\n            'explicit_invocation_required',\n            'Claude may only be consulted when the user explicitly names Claude/Anthropic '\n            'in the current request; pass the user\\'s exact words as user_request.',\n        )\n    if len(user_request) > MAX_USER_REQUEST_CHARS:\n        raise BridgeError(\n            'explicit_invocation_required',\n            'user_request exceeds ' + str(MAX_USER_REQUEST_CHARS) + ' characters',\n        )\n    user_request_text = user_request.strip()\n\n    if not isinstance(role, str) or role not in ROLE_PROMPTS:\n        raise BridgeError(\n            'invalid_arguments',\n            'role must be one of: ' + ', '.join(ROLE_PROMPTS),\n        )\n    task_text = validate_text('task', task, MAX_TASK_CHARS, required=True)\n    context_text = validate_text('context', context, MAX_CONTEXT_CHARS, required=False)\n\n    if files is None:\n        rel_files: List[str] = []\n    elif isinstance(files, list):\n        if not all(isinstance(item, str) for item in files):\n            raise BridgeError('invalid_arguments', 'files must be a list of strings')\n        rel_files = list(files)\n    else:\n        raise BridgeError('invalid_arguments', 'files must be a list of strings or null')\n\n    info = load_config(config_path)\n    if info['errors']:\n        raise BridgeError('config_error', '; '.join(info['errors']))\n    cfg = info['values']\n    validate_call_config(cfg)\n\n    validated_root: Optional[Path] = None\n    if root is not None:\n        validated_root = validate_root(root)\n    if rel_files and validated_root is None:\n        raise BridgeError('bad_root', '--root is required when --files is used')\n\n    forbidden_roots = default_workspace_roots()\n    if validated_root is not None:\n        forbidden_roots.append(validated_root)\n\n    api_key, key_source = load_api_key(cfg, forbidden_roots)\n    entries = collect_files(str(validated_root), rel_files) if rel_files else []\n    files_block = render_files(entries) if entries else ''\n    payload = build_payload(cfg, role, task_text, context_text, files_block)\n    raw = call_anthropic(cfg, payload, api_key, opener=opener)\n\n    result = build_result(cfg, role, raw)\n    result['key_source'] = key_source\n    result['files_used'] = [entry['path'] for entry in entries]\n    result['user_request'] = user_request_text\n    return result"
