      "new": "def status_report(config_path: Path) -> Dict[str, Any]:\n    info = load_config(config_path)\n    errors = list(info['errors'])\n    cfg = info['values']\n\n    raw_env_name = cfg.get('api_key_env')\n    if raw_env_name is None:\n        env_name = DEFAULT_API_KEY_ENV\n        env_name_valid = True\n    elif isinstance(raw_env_name, str) and raw_env_name.strip():\n        env_name = raw_env_name\n        env_name_valid = True\n    else:\n        env_name = DEFAULT_API_KEY_ENV\n        env_name_valid = False\n\n    env_present = False\n    if env_name_valid:\n        env_value = os.environ.get(env_name)\n        env_present = bool(env_value and env_value.strip())\n\n    raw_file = cfg.get('api_key_file')\n    file_configured = isinstance(raw_file, str) and bool(raw_file.strip())\n\n    model = cfg.get('model')\n    max_tokens = cfg.get('max_tokens')\n    model_ok = isinstance(model, str) and bool(model.strip())\n    tokens_ok = (\n        isinstance(max_tokens, int)\n        and not isinstance(max_tokens, bool)\n        and max_tokens > 0\n    )\n    configured = (\n        bool(info['present'])\n        and not errors\n        and env_name_valid\n        and (env_present or file_configured)\n    )\n\n    return {\n        'ok': True,\n        'kind': 'claude_status',\n        'configured': configured,\n        'call_ready': configured and model_ok and tokens_ok,\n        'config_present': bool(info['present']),\n        'config_path': str(config_path),\n        'base_url': cfg.get('base_url') or OFFICIAL_BASE_URL,\n        'api_version': cfg.get('api_version') or DEFAULT_API_VERSION,\n        'model': model,\n        'max_tokens': max_tokens,\n        'thinking': cfg.get('thinking'),\n        'timeout_seconds': cfg.get('timeout_seconds') or DEFAULT_TIMEOUT_SECONDS,\n        'workspace_id_configured': bool(cfg.get('workspace_id')),\n        'api_key_env': env_name if env_name_valid else None,\n        'api_key_env_valid': env_name_valid,\n        'api_key_env_present': env_present,\n        'api_key_file_configured': file_configured,\n        'errors': errors,\n        'notes': list(STATUS_NOTES),\n    }"
