      "file": "tools/claude-advisor/preparation/draft/bridge.py",
      "old": "def handle_tool_call(msg_id: Any, params: Dict[str, Any], config_path: Path) -> Dict[str, Any]:\n    name = params.get('name')\n    arguments = params.get('arguments')\n    if arguments is None:\n        arguments = {}\n    if not isinstance(arguments, dict):\n        return rpc_error(msg_id, -32602, 'tool arguments must be an object')\n\n    if name == 'claude_status':\n        unknown = sorted(set(arguments))\n        if unknown:\n            return tool_text_result(msg_id, BridgeError(\n                'invalid_arguments', 'unknown arguments: ' + ', '.join(unknown)).to_json())\n        return tool_text_result(msg_id, status_report(config_path))\n\n    if name == 'claude_consult':\n        unknown = sorted(set(arguments) - ALLOWED_CONSULT_ARGS)\n        if unknown:\n            return tool_text_result(msg_id, BridgeError(\n                'invalid_arguments', 'unknown arguments: ' + ', '.join(unknown)).to_json())\n        try:\n            result = run_consult(\n                config_path,\n                arguments.get('task'),\n                arguments.get('role'),\n                arguments.get('context'),\n                arguments.get('root'),\n                arguments.get('files'),\n            )\n        except BridgeError as exc:\n            return tool_text_result(msg_id, exc.to_json())\n        return tool_text_result(msg_id, result)\n\n    return rpc_error(msg_id, -32602, 'unknown tool: ' + str(name))",
      "new": "def handle_tool_call(msg_id: Any, params: Dict[str, Any], config_path: Path) -> Dict[str, Any]:\n    name = params.get('name')\n    arguments = params.get('arguments')\n    if arguments is None:\n        arguments = {}\n    if not isinstance(arguments, dict):\n        return rpc_error(msg_id, -32602, 'tool arguments must be an object')\n\n    if name == 'claude_status':\n        unknown = sorted(set(arguments))\n        if unknown:\n            return tool_text_result(msg_id, BridgeError(\n                'invalid_arguments', 'unknown arguments are not allowed').to_json())\n        return tool_text_result(msg_id, status_report(config_path))\n\n    if name == 'claude_consult':\n        unknown = sorted(set(arguments) - ALLOWED_CONSULT_ARGS)\n        if unknown:\n            return tool_text_result(msg_id, BridgeError(\n                'invalid_arguments', 'unknown arguments are not allowed').to_json())\n        try:\n            result = run_consult(\n                config_path,\n                arguments.get('task'),\n                arguments.get('role'),\n                arguments.get('context'),\n                arguments.get('root'),\n                arguments.get('files'),\n                user_request=arguments.get('user_request'),\n            )\n        except BridgeError as exc:\n            return tool_text_result(msg_id, exc.to_json())\n        return tool_text_result(msg_id, result)\n\n    return rpc_error(msg_id, -32602, 'unknown tool')"
