      "old": "def handle_rpc(message: Dict[str, Any], config_path: Path) -> Optional[Dict[str, Any]]:\n    method = message.get('method')\n    msg_id = message.get('id')\n    params = message.get('params')\n    if not isinstance(params, dict):\n        params = {}\n\n    if method == 'initialize':\n        requested = params.get('protocolVersion')\n        negotiated = requested if requested in PROTOCOL_VERSIONS else FALLBACK_PROTOCOL_VERSION\n        return {\n            'jsonrpc': '2.0',\n            'id': msg_id,\n            'result': {\n                'protocolVersion': negotiated,\n                'capabilities': {'tools': {'listChanged': False}},\n                'serverInfo': MCP_SERVER_INFO,\n            },\n        }\n\n    if isinstance(method, str) and method.startswith('notifications/'):\n        return None\n\n    if method == 'ping':\n        return {'jsonrpc': '2.0', 'id': msg_id, 'result': {}}\n\n    if method == 'tools/list':\n        return {'jsonrpc': '2.0', 'id': msg_id, 'result': {'tools': TOOL_DEFINITIONS}}\n\n    if method == 'tools/call':\n        return handle_tool_call(msg_id, params, config_path)\n\n    return rpc_error(msg_id, -32601, 'method not found: ' + str(method))",
      "new": "def handle_rpc(message: Dict[str, Any], config_path: Path) -> Optional[Dict[str, Any]]:\n    if not isinstance(message, dict):\n        return None\n    if 'id' not in message:\n        return None\n\n    msg_id = message.get('id')\n    if message.get('jsonrpc') != '2.0':\n        return rpc_error(msg_id, -32600, 'invalid request')\n\n    method = message.get('method')\n    if not isinstance(method, str):\n        return rpc_error(msg_id, -32600, 'invalid request')\n\n    if 'params' in message and not isinstance(message.get('params'), dict):\n        return rpc_error(msg_id, -32602, 'invalid params')\n    params = message.get('params') if isinstance(message.get('params'), dict) else {}\n\n    if method.startswith('notifications/'):\n        return None\n\n    if method == 'initialize':\n        requested = params.get('protocolVersion')\n        negotiated = requested if requested in PROTOCOL_VERSIONS else FALLBACK_PROTOCOL_VERSION\n        return {\n            'jsonrpc': '2.0',\n            'id': msg_id,\n            'result': {\n                'protocolVersion': negotiated,\n                'capabilities': {'tools': {'listChanged': False}},\n                'serverInfo': MCP_SERVER_INFO,\n            },\n        }\n\n    if method == 'ping':\n        return {'jsonrpc': '2.0', 'id': msg_id, 'result': {}}\n\n    if method == 'tools/list':\n        return {'jsonrpc': '2.0', 'id': msg_id, 'result': {'tools': TOOL_DEFINITIONS}}\n\n    if method == 'tools/call':\n        return handle_tool_call(msg_id, params, config_path)\n\n    return rpc_error(msg_id, -32601, 'method not found')"
