      "new": "def run_mcp_server(config_path: Path) -> int:\n    for line in sys.stdin:\n        stripped = line.strip()\n        if not stripped:\n            continue\n        try:\n            message = json.loads(stripped)\n        except json.JSONDecodeError:\n            write_message(rpc_error(None, -32700, 'parse error'))\n            continue\n        if not isinstance(message, dict):\n            write_message(rpc_error(None, -32600, 'invalid request'))\n            continue\n        try:\n            response = handle_rpc(message, config_path)\n        except Exception:\n            if 'id' in message:\n                response = rpc_error(message.get('id'), -32603, 'internal error')\n            else:\n                response = None\n        if response is not None:\n            write_message(response)\n    return 0"
